import{z as i,x as o,o as e,c as s,q as r,j as t,D as E,d as B,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"再平衡策略学","description":"","frontmatter":{"title":"再平衡策略学","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-rebalancing.md","filePath":"quant/pf-rebalancing.md","lastUpdated":1791063341000}'),p={name:"quant/pf-rebalancing.md"};function d(u,a,m,C,h,c){const n=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=r('<h1 id="再平衡策略学" tabindex="-1">再平衡策略学 <a class="header-anchor" href="#再平衡策略学" aria-label="Permalink to &quot;再平衡策略学&quot;">​</a></h1><div class="epigraph"><p>再平衡不是维护费，是一张卖出波动率的保单：震荡市里它持续收租，单边市里它把凸性赔付出去。</p><footer>—— 据 Perold and Sharpe, Dynamic Strategies for Asset Allocation, Financial Analysts Journal, 1988；Constantinides, Journal of Economic Theory, 1986 整理</footer></div><p><a href="/quant/pf-blackbox-optimizers">上一课</a>把非凸目标的求解收口：先凸化外围，黑盒只碰真正的核，搜索次数进台账。到此为止，优化器每期输出一个目标权重；缺口是目标点之间的路——何时动、动多少、动的时候付什么。本课进入策略维度，把再平衡当作政策来设计与评估。主干课的<a href="/quant/rebalance-rules">再平衡规则</a>已写日历、阈值与禁交易带的机制，<a href="/quant/rb-rebalance">风险预算再平衡</a>写了贡献空间的监控；本课不重复规则清单，写的是把这些规则当作一个联合设计问题来选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>目标权重每期重算，把它实现成持仓却是一套独立政策：按日历推回、按带宽触发、推到带边还是完全复位、部分调整还是一次到位。<span class="marginnote">带宽就是允许权重漂移的容忍区间。数字实例：目标股债各 50%、带宽 ±5%——股票上涨使占比到 56% 时触发再平衡，卖股买债拉回目标；带内不动是为了省交易费，带外必须动是为了不让风险漂走，宽与窄是在这两笔账之间讨价。</span>政策选错错在哪：带太紧，佣金、冲击与<a href="/quant/turnover-penalty">换手惩罚</a>把 alpha 吃光；带太松，风险漂移——波动翻倍而仓位未动，政策目标早已落空。更根本地，再平衡本身有收益结构：恒定混合是卖赢买输，在均值回复的震荡市里持续收获<a href="/quant/rebalancing-premium">再平衡溢价</a>，在单边趋势市里把凸性赔付出去（Perold 与 Sharpe 1988 的经典对照）。把它当中性维护费，就会在趋势行情里把亏损归咎于「运气」，而那笔亏损是政策自带的负债。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把再平衡参数化成一个政策对象：触发、复位方式与成本核写在一起联合设计，三个设计资源——动态规划的无交易区、部分调整的速度公式、风险预算的推回对象——各回答问题的一段。评估永远带成本核做净额比较：带宽的宽严在净收益与风险漂移之间讨价，不在样本内夏普里挑最亮的那根。</p><h3 id="政策的参数化" tabindex="-1">政策的参数化 <a class="header-anchor" href="#政策的参数化" aria-label="Permalink to &quot;政策的参数化&quot;">​</a></h3><p>把再平衡政策写成一个对象：\\((\\tau,\\delta,\\kappa)\\)——触发（日历 \\(\\tau\\) 或带宽 \\(\\delta\\)）、复位方式（推到带边或完全复位）、成本核 \\(\\kappa\\)（佣金、冲击与税）。三个方向的设计资源：其一，动态规划的语言把「何时动」写成带费用的最优停时，比例成本下的无交易区是自由边界问题（Constantinides 1986；<a href="/quant/dynamic-programming-rebalance">动态规划与再平衡</a>）；其二，Gârleanu 与 Pedersen（2013，见 <a href="/quant/garleanu-pedersen">Gârleanu–Pedersen 动态交易</a>）把复位方式写成部分调整：\\(w_{t+1}-w_t=\\kappa\\,(w_t^{\\ast}-w_t)\\)，调整速度由信号可预测性与成本之比决定——目标与路径合并成一个策略；<span class="marginnote">部分调整公式里的 \\(\\kappa\\) 就是「每期把现有偏离修掉几成」：\\(\\kappa=0.5\\) 表示偏离 4% 时本期只修 2%，剩下慢慢来；\\(\\kappa=1\\) 是一次复位。信号越持久、成本越高，最优 \\(\\kappa\\) 越小——修得太快等于为噪音付全额手续费。</span>其三，风险预算的场合，推回的对象是欧拉贡献而不是名义权重（<a href="/quant/rb-rebalance">风险预算再平衡</a>），两套带宽不能混用。</p>',9)),(e(),t(l,null,{default:E(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WSTAR%5B%22%E6%9C%AC%E6%9C%9F%E7%9B%AE%E6%A0%87%E6%9D%83%E9%87%8D%20w*%22%5D%20--%3E%20MON%5B%22%E5%81%8F%E7%A6%BB%E7%9B%91%E6%8E%A7%EF%BC%9A%E6%9D%83%E9%87%8D%E4%B8%8E%E9%A3%8E%E9%99%A9%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20MON%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20HOLD%5B%22%E7%AD%89%E5%BE%85%EF%BC%9A%E4%B8%8D%E4%BA%A4%E6%98%93%22%5D%0A%20%20MON%20--%3E%7C%E5%B8%A6%E5%A4%96%7C%20PUSH%5B%22%E5%A4%8D%E4%BD%8D%EF%BC%9A%E5%B8%A6%E8%BE%B9%E6%88%96%E9%83%A8%E5%88%86%E8%B0%83%E6%95%B4%22%5D%0A%20%20PUSH%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E6%A0%B8%EF%BC%9A%E4%BD%A3%E9%87%91%E3%80%81%E5%86%B2%E5%87%BB%E4%B8%8E%E7%A8%8E%22%5D%0A%20%20COST%20--%3E%20EVAL%5B%22%E6%94%BF%E7%AD%96%E8%AF%84%E4%BC%B0%EF%BC%9A%E5%87%80%E6%94%B6%E7%9B%8A%E4%B8%8E%E9%A3%8E%E9%99%A9%E6%BC%82%E7%A7%BB%22%5D%0A%20%20EVAL%20--%3E%7C%E5%8F%8D%E9%A6%88%E8%B0%83%E5%B8%A6%7C%20MON%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>凸性的价格是这门课的核心会计。恒定混合在每次偏离后卖强买弱，等价于持续向市场卖出趋势保险；<a href="/quant/cppi-tipp">组合保险 CPPI / TIPP</a> 是它的镜像——买凸性的一方在趋势市获利、在震荡市被磨损。所以「再平衡有溢价」不是免费午餐的承诺，是波动与均值回复的报酬，且符号随体制翻转。为什么带宽是政策而非细节：两只基金持有同样的目标权重、不同的带，收益分布可以差出一个风格；带还决定了与其它规则的拥挤——当大量纪律化资金共享相似的日历与带宽时，执行时点聚集，成本自我抬高（<a href="/quant/index-rebalance-arb">指数调仓套利</a>写的是同一机制的指数版）。带宽与波动目标的交互也在此：波动上升时目标仓位下降，若带太松，降仓被延迟到风险已经兑现之后——<a href="/quant/vol-targeting">波动目标</a>的风险控制就被再平衡政策抵消了一半。</p>',2)),(e(),t(l,null,{default:E(()=>[A(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%8A%A8%E4%BD%BF%E6%9D%83%E9%87%8D%E5%81%8F%E7%A6%BB%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20SEL%5B%22%E5%8D%96%E5%BC%BA%E4%B9%B0%E5%BC%B1%EF%BC%9A%E6%81%92%E5%AE%9A%E6%B7%B7%E5%90%88%E7%9A%84%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20SEL%20--%3E%20Q%7B%22%E8%A1%8C%E6%83%85%E5%B1%9E%E4%BA%8E%E5%93%AA%E4%B8%80%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E9%9C%87%E8%8D%A1%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%22%7C%20WIN%5B%22%E4%B9%B0%E5%BC%B1%E7%9A%84%E5%8F%8D%E5%BC%B9%E5%9B%9E%E6%9D%A5%EF%BC%8C%E6%8C%81%E7%BB%AD%E6%94%B6%E7%A7%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8D%95%E8%BE%B9%E8%B6%8B%E5%8A%BF%22%7C%20LOSE%5B%22%E8%B6%8A%E5%8D%96%E8%B6%8A%E6%B6%A8%E6%88%96%E8%B6%8A%E4%B9%B0%E8%B6%8A%E8%B7%8C%EF%BC%8C%E5%87%B8%E6%80%A7%E8%A2%AB%E8%B5%94%E4%BB%98%22%5D%0A%20%20WIN%20--%3E%20PREM%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%E6%BA%A2%E4%BB%B7%E5%85%A5%E8%B4%A6%22%5D%0A%20%20LOSE%20--%3E%20INS%5B%22%E8%B7%91%E8%BE%93%E4%B8%8D%E5%8A%A8%E7%9A%84%E7%BB%84%E5%90%88%EF%BC%8C%E5%83%8F%E5%9C%A8%E9%80%81%E4%BF%9D%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：以为「再平衡有溢价」是稳定的超额收益。它赚的其实是波动与均值回复的钱：先深跌后反弹的 V 型市里持续收租；而单边趋势市里恒定混合一直卖涨买跌，显著跑输不动的组合——溢价的符号随体制翻转，不是免费午餐。</span></p><p><span class="marginnote">比例交易成本下，最优无交易区宽度按成本的立方根缩放（Davis–Norman 1990 的自由边界）：成本减半，带宽只收窄到约 \\(2^{-1/3}\\approx 0.79\\)——带宽对成本不敏感的直觉，常常让人把带设得太紧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写日历/阈值机制的条目（<a href="/quant/rebalance-rules">再平衡规则</a>），不重推风险预算的监控量（<a href="/quant/rb-rebalance">风险预算再平衡</a>），不展开动态规划的完整形式（<a href="/quant/dynamic-programming-rebalance">动态规划与再平衡</a>）。信号半衰期与持有期的匹配在<a href="/quant/factor-decay-turnover">因子衰减与换手</a>，那是目标权重的生产端；本课只管目标之后的路。税的维度进入成本核之后完全改变政策形状——无交易区会变得不对称，这是下一课的对象。政策回测若不带真实摩擦与税，得出的「最优带」只是另一个样本内最优。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>再平衡是政策不是维护：触发、复位方式、成本核三件联合设计，收益结构自带凸性敞口。</li><li>再平衡溢价是波动收割，趋势市中符号翻转；把它当免费午餐会误配带宽。</li><li>无交易区宽度按成本立方根缩放；部分调整把目标与路径合并成一个策略。</li><li>带宽决定与波动目标、风险预算及其它纪律化资金的交互，是风格变量。</li><li>出处：Perold &amp; Sharpe, <em>FAJ</em>, 1988；Constantinides, <em>JET</em>, 1986；Gârleanu &amp; Pedersen, <em>RFS</em>, 2013；Davis &amp; Norman, <em>Mathematical Finance</em>, 1990。</li></ul>',6))])}const _=i(p,[["render",d]]);export{f as __pageData,_ as default};
